package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.Instant;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.DateTimeParser;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class DateTimeFormatter_parseInto_TriageGen1Test {

    private DateTimeFormatter formatter;
    private ReadWritableInstant mockInstant;
    private DateTimeParser mockParser;

    @Before
    public void setUp() {
        // We use a real formatter instance to ensure the internal state (iOffsetParsed, iZone, etc.) 
        // is handled correctly, but we will mock the parser to control the parsing logic.
        formatter = DateTimeFormat.forPattern("yyyy-MM-dd").parseAs(DateTimeParser.class);
        mockInstant = mock(ReadWritableInstant.class);
        mockParser = mock(DateTimeParser.class);
    }

    /**
     * Tests that passing a null instant throws IllegalArgumentException.
     */
    @Test
    public void testParseInto_NullInstant_ThrowsException() {
        assertThrows(IllegalArgumentException.class, () -> {
            formatter.parseInto(null, "2023-01-01", 0);
        });
    }

    /**
     * Tests the standard successful parsing path.
     */
    @Test
    public void testParseInto_Success() {
        // Setup mock instant
        long millis = 1672531200000L; // 2023-01-01
        when(mockInstant.getMillis()).thenReturn(millis);
        when(mockInstant.getChronology()).thenReturn(org.joda.time.ISOChronology.getInstanceUTC());

        // Setup mock parser behavior
        // The parser.parseInto(bucket, text, position) is called.
        // We simulate the parser updating the bucket.
        // Since DateTimeParserBucket is internal, we rely on the parser's interaction with the bucket.
        // However, in a real scenario, the parser writes to the bucket.
        // For this test, we use a real formatter with a real pattern to ensure the bucket logic is exercised.
        DateTimeFormatter realFormatter = DateTimeFormat.forPattern("yyyy-MM-dd");
        MutableDateTime mutableDateTime = new MutableDateTime(millis);

        int result = realFormatter.parseInto(mutableDateTime, "2023-01-01", 0);

        assertEquals(10, result);
        assertEquals(millis, mutableDateTime.getMillis());
    }

    /**
     * Tests the branch where iOffsetParsed is true and bucket has an offset.
     */
    @Test
    public void testParseInto_WithOffsetParsed() {
        DateTimeFormatter offsetFormatter = DateTimeFormat.forPattern("yyyy-MM-dd Z")
                .withOffsetParsed();

        MutableDateTime mutableDateTime = new MutableDateTime(1672531200000L);
        String text = "2023-01-01 +05:00";

        int result = offsetFormatter.parseInto(mutableDateTime, text, 0);

        assertEquals(15, result);
        // Check if zone was updated based on parsed offset
        assertEquals(DateTimeZone.forOffsetHours(5), mutableDateTime.getZone());
    }

    /**
     * Tests the branch where iOffsetParsed is false but bucket has a zone.
     */
    @Test
    public void testParseInto_WithZoneInBucket() {
        // Using a pattern that implies a zone but doesn't explicitly parse the offset integer 
        // via the iOffsetParsed flag logic if we were to manipulate it.
        // Here we test the 'else if (bucket.getZone() != null)' branch.
        DateTimeFormatter zoneFormatter = DateTimeFormat.forPattern("yyyy-MM-dd")
                .withZone(DateTimeZone.forID("America/New_York"));

        MutableDateTime mutableDateTime = new MutableDateTime(1672531200000L);

        int result = zoneFormatter.parseInto(mutableDateTime, "2023-01-01", 0);

        assertEquals(10, result);
        assertEquals(DateTimeZone.forID("America/New_York"), mutableDateTime.getZone());
    }

    /**
     * Tests the branch where iZone is explicitly set on the formatter.
     */
    @Test
    public void testParseInto_WithExplicitZone() {
        DateTimeZone explicitZone = DateTimeZone.UTC;
        DateTimeFormatter explicitZoneFormatter = DateTimeFormat.forPattern("yyyy-MM-dd")
                .withZone(explicitZone);

        MutableDateTime mutableDateTime = new MutableDateTime(1672531200000L);

        explicitZoneFormatter.parseInto(mutableDateTime, "2023-01-01", 0);

        assertEquals(explicitZone, mutableDateTime.getZone());
    }

    /**
     * Tests the branch with Pivot Year.
     */
    @Test
    public void testParseInto_WithPivotYear() {
        DateTimeFormatter pivotFormatter = DateTimeFormat.forPattern("yy-MM-dd")
                .withPivotYear(2000);

        MutableDateTime mutableDateTime = new MutableDateTime(1672531200000L);

        // "23" with pivot 2000 should be 2023
        int result = pivotFormatter.parseInto(mutableDateTime, "23-01-01", 0);

        assertEquals(8, result);
        assertEquals(2023, mutableDateTime.getYear());
    }

    /**
     * A helper class to satisfy the ReadWritableInstant interface for testing.
     */
    private static class MutableDateTime extends org.joda.time.MutableDateTime {
        public MutableDateTime(long instant) {
            super(instant);
        }
    }
}
